/// A document of the "notes" collection. A property stays nil until it is set or read.
public struct Note: Sendable, Equatable {
    public var id: Int?
    public var text: String?
    public var authorId: Int?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: Int? = nil, text: String? = nil, authorId: Int? = nil) {
        self.id = id
        self.text = text
        self.authorId = authorId
    }
}

extension Note: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Note {
        var entity = Note(
            id: try Bson.read(document, "_id", Bson.asInt32),
            text: try Bson.read(document, "text", Bson.asText),
            authorId: try Bson.read(document, "authorId", Bson.asInt32))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofInt32)
        try Bson.write(&document, "text", self.text, Bson.ofText)
        try Bson.write(&document, "authorId", self.authorId, Bson.ofInt32)
        return document
    }
}

