            let uow = MemoryUnitOfWork()
            let service = UserService(unitOfWork: uow)
            let row = Factories.newUser(1)
            let first = try await service.createUser(createOf(row))
            var again = Factories.newUser(2)
            again.email = first.email
            #expect(isConflict(await refusal { try await service.createUser(createOf(again)) }))
        }

        @Test func keepsItsOwnUniqueValue() async throws {
            let uow = MemoryUnitOfWork()
            let service = UserService(unitOfWork: uow)
            let row = Factories.newUser(1)
            let created = try await service.createUser(createOf(row))
            let updated = try await service.updateUser(created.id, UserUpdate(email: .set(created.email)))
            #expect(created.email == updated.email)
        }

        @Test func saysWhenARowIsMissing() async throws {
            let uow = MemoryUnitOfWork()
            let service = UserService(unitOfWork: uow)
            #expect(isNotFound(await refusal { try await service.getUser(999999) }))
        }

